function MapDecryptionPlayer:StartPlay()
    self.waitCo = cs_coroutine.start(function()

        -- printInfo("MapDecryptionPlayer start")
        local director = nil
        local pre = nil
        if isNull(self.markers) then
            return
        end
        for i = 1, self.markers.Count do
            director = self.markers[i - 1].Director:Resolve(self.processor.DirectorControl)
            if not isNull(director) then
                KTool.SetActive(director.gameObject, true)
                
                self:BindModel(director, self.model, self._protagonistModel)

                local name = director.gameObject.name
                if name == "story_spring_01_t01" then
                    -- self:SetCameraStack(true)
                    -- KTool.SetActive(self.chapterNewUI.gameObject, false)
                    self:SetChapterNewUIState(false)

                elseif name == "story_spring_02" then
                    self:SetChapterNewUIState(true)
                    -- self:SetCameraStack(false)
                    -- KTool.SetActive(self.chapterNewUI.gameObject, true)

                end

                if not isNull(pre) then
                    KTool.SetActive(pre, false)
                end

                pre = director
                director:Play()

                if not isNull(self.processor.OnSingleChapterStart) then
                    self.processor.OnSingleChapterStart(director)
                end

                if director.extrapolationMode == CS.UnityEngine.Playables.DirectorWrapMode.Loop then
                    self.waitForBreak = true
                    if self._callback then
                        self._callback()
                    end
                    -- Events.Broadcast("MapDecryptionLoopEvent")
                    -- KTool.SetActive(self.touch, true)
                    
                    while self.waitForBreak do
                        coroutine.yield()
                    end
                    
                else
                    coroutine.yield(WaitForTimelineFinish(director))
                end
                

                if not isNull(self.processor.OnSingleChapterFinish) then
                    self.processor.OnSingleChapterFinish(director)
                end
                --if director.gameObject.name == "" then
                --    KTool.SetActive(self.model, false)
                --end
            end
        end

        -- self._isRecoveryCamera = true
        -- camCtrl:ClearCameraStack(camCtrl.mainCamera)
        -- camCtrl:InitCameraStack(camCtrl.mainCamera)
        -- self:SetCameraStack(true)

        if not isNull(self.processor.OnChapterFinish) then
            self.processor.OnChapterFinish()
        end

    end)

    return self.waitCo
end

function MapDecryptionPlayer:BindModel(director, model, protagonistModel)
    local trackName2Object = {
        ["108008_ani"] = model,
        ["108008_act"] = model,
        ["20002_ani"]  = protagonistModel,
    }
    
    self._modelTrackSources = GachaponUtils.BindTimelines(director, trackName2Object, function (streamName, object)
        if streamName == "20002_ani" then
            object.transform:SetParent(director.transform)
            KTool.SetActive(object.gameObject, true)
        end
    end)

    if not isNull(model) then
        model.transform:SetParent(director.transform:Find(HomeLoc))
        model.transform.localRotation = Quaternion.Euler(0,0,0)
        KTool.ResetTransform(model.transform)
    end
    
end

