    if not isNull(self.control) then
        KTool.SetActive(self.control.gameObject, isShow)
        
    end
end

function MapDecryptionPlayer:OnDestroy()
    -- self:SetCameraStack(true)
    KTool.SetActive(camCtrl.uiCamera,   true)
    KTool.SetActive(camCtrl.mainCamera, true)
    --- 由于人物会跟随场景一起销毁 理论上不用恢复
    -- if not isNull(self.model) then
    --     local r = self.model
    --     r.transform:SetParent(self.initState.parent)
    --     r.transform.localPosition = self.initState.localPosition
    --     r.transform.localRotation = self.initState.localRotation
    --     r.transform.localScale = self.initState.localScale
    --     KTool.SetActive(r, self.initState.active)
    -- end
    local director
    if not isNull(self.markers) and self._modelTrackSources then
        for i = 1, self.markers.Count do
            director = self.markers[i - 1].Director:Resolve(self.processor.DirectorControl)
            if not isNull(director) then
                GachaponUtils.ClearTimelineBinding(director, self._modelTrackSources)
            end
        end
    end
    if self.__OnStopLoopEvent then
        Events.RemoveListener(MapDecryptionStopLoopEvent, self.__OnStopLoopEvent)
    end
    if self.waitCo ~= nil then
        cs_coroutine.stop(self.waitCo)
        self.waitCo = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return MapDecryptionPlayer